export default {"id":"ableton-level-11","number":11,"title":"Appendices","skillBand":"Textbook","duration":"From the course textbook","summary":"- Appendix ID: ableton-app-push - Curriculum Status: Optional Hardware Reference (Not on the Required Core Learning Path)","modules":[{"id":"ableton-m-1-1","code":"1","title":"Appendix: Push 1 & Push 2 Reference Guide","blurb":"- Appendix ID: ableton-app-push - Curriculum Status: Optional Hardware Reference (Not on the Required Core Learning Path)","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"ableton-appendix-push-1-and-2-reference","title":"# Appendix: Push 1 & Push 2 Reference Guide","blocks":[{"type":"step","title":"Metadata & Context","blocks":[{"type":"list","items":["<strong>Appendix ID:</strong> <code>ableton-app-push</code>","<strong>Curriculum Status:</strong> Optional Hardware Reference (Not on the Required Core Learning Path)","<strong>Manual Spine References:</strong> Chapter 34 (<em>Using Push 1</em>), Chapter 35 (<em>Using Push 2</em>)","<strong>Studio Scope Context:</strong> Reference guide for studio environments adding Ableton Push 1 or Push 2 hardware. Hardware mastery is optional and does not gate core curriculum progress."],"ordered":false}]},{"type":"step","title":"Section 1: Push Hardware Architecture Overview","blocks":[{"type":"prose","html":"Ableton Push (Push 1 and Push 2) is a dedicated hardware instrument and control surface designed to integrate directly with Live's Session grid, MIDI sequencing, and device parameters:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">┌─────────────────────────────────────────────────────────────────────────────┐\n│                           PUSH HARDWARE TOPOLOGY                            │\n├─────────────────────────────────────────────────────────────────────────────┤\n│  [8 TOUCH-SENSITIVE ENCODERS] ──► Auto-maps to active Device View macros    │\n│  [HIGH-RESOLUTION COLOR DISPLAY (Push 2)] ──► Shows waveforms, filters, LOM │\n│                                                                             │\n│  [64-PAD VELOCITY/PRESSURE MATRIX (8x8)]                                    │\n│  ├── Mode 1: Clip Launch Mode (Launches Session clips and scenes)           │\n│  ├── Mode 2: Melodic In-Key Keyboard (Scale-locked isomorphic keyboard)     │\n│  └── Mode 3: 16-Velocity / 32-Step Drum Sequencer (Real-time step sequencing│\n│                                                                             │\n│  [TOUCH STRIP] ──► Pitch bend, mod wheel, and scrolling navigation         │\n└─────────────────────────────────────────────────────────────────────────────┘</pre>"}]},{"type":"step","title":"Section 2: Core Operating Modes","blocks":[{"type":"heading","text":"2.1 The 64-Pad Matrix Modes","level":4},{"type":"list","items":["<strong>Note Mode (Melodic Instruments):</strong>","<strong>In-Key Mode:</strong> The 64 pads map strictly to notes within the active musical scale (e.g., D Minor). Root notes light up blue/orange; scale degrees light up white. Incorrect notes are physically removed from the pad grid.","<strong>Chromatic Mode:</strong> Out-of-scale notes are unlit but playable, providing a complete 64-pad chromatic keyboard layout.","<strong>Drum Mode (Drum Racks):</strong>","<strong>16-Pad Play Zone (Lower-Left 4x4):</strong> Plays the 16 visible pads of the active Drum Rack.","<strong>Step Sequencer Zone (Top 4x8):</strong> Displays a 32-step running rhythmic sequence for the currently selected drum pad.","<strong>Loop Length Selector (Lower-Right 4x4):</strong> Selects which bar/page of the pattern is displayed on the step sequencer.","<strong>Session Mode:</strong>","The 8x8 pad matrix transforms into a mirror of Live's Session View grid. Pads reflect clip colors, playing states (flashing green), and empty stop slots."],"ordered":true}]},{"type":"step","title":"Section 3: Device Control & Sample Warping on Push 2","blocks":[{"type":"list","items":["<strong>Device Parameter Navigation:</strong> Encoders automatically map to banks of 8 parameters across native devices (<strong>Operator</strong>, <strong>Drift</strong>, <strong>Analog</strong>, <strong>EQ Eight</strong>, <strong>Compressor</strong>).","<strong>Sample Waveform Manipulation (Push 2):</strong> When using <strong>Simpler</strong>, the high-resolution display renders the sample waveform in real time. Encoders allow direct adjustment of Start/End markers, Warp markers, slice sensitivity, and filter cutoff directly from the hardware without looking at the computer monitor."],"ordered":false}]},{"type":"step","title":"Primary Sources & Grounding Citations","blocks":[{"type":"list","items":["<strong>Live 12 Reference Manual:</strong> Chapter 34 (<em>Using Push 1: 34.1–34.14</em>), Chapter 35 (<em>Using Push 2: 35.1–35.15</em>).","<strong>Ableton Knowledgebase:</strong> <em>Push 2 Manual and Reference Guides</em>."],"ordered":false}]}],"minutes":8}],"exercises":[]}]};
